from __future__ import absolute_import

import logging

from taf.selenium.gnb.oam.coam.cu.pages import v22R3
from taf.selenium.gnb.oam.coam.cu import pages
from taf.selenium.gnb.oam.coam.cu.pages.panels.view import ViewPanel

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class Diagnostic(v22R3.Diagnostic):
    """
    The class corresponding to diagnostic page on selenium_coam_cu. web, all operations under diagnostic
    page will be implemented or added in its corresponding classes.
    """

    def __init__(self, driver, version):
        super(Diagnostic, self).__init__(driver, version)
        self._instance_dict.update({"TWAMP Metric": TWAMPMetric(driver, version)})
        self._instance_dict.update({"Snapshot": SnapshotPageV22R4(driver, version)})


class SnapshotPageV22R4(pages.SnapshotPage):
    """
    As a class will be called by Diagnostic, all operations Snapshot will be implemented under this class.
    """
    MENU_ROUTE_LIST = ['stethoscope', 'Snapshot', 'Snapshot Collection']

    def __init__(self, driver, version):
        super(SnapshotPageV22R4, self).__init__(driver, version)


class TWAMPMetric(object):
    """
    As a class will be called by PMTU discovery, all operations PMTU discovery will be implemented under this class.
    """
    MENU_ROUTE_LIST = ['stethoscope', 'TWAMP Metric']

    def __init__(self, driver, version):
        self._view_panel = TWAMPMetricViewPanel(driver, version)

    def get_twamp_metric(self, session, timeout):
        """
         This keyword is used to get twamp metrics the and return result
        :param session: str, session in which TWAMP metrix needs to collected
        :param timeout: int, timeout for the element be available to click

        :return: Dict, return the dictionary of twamp metrics result
        """
        return self._view_panel.get_twamp_metric(session, timeout)


class TWAMPMetricViewPanel(ViewPanel):
    def __init__(self, driver, version):
        self.driver = driver
        super(TWAMPMetricViewPanel, self).__init__(driver, version)

    def get_twamp_metric(self, session, timeout):
        """
        This keyword is used to get twamp metrics the and return result
        :param session: str, session in which TWAMP metrix needs to collected
        :param timeout: int, timeout for the element be available to click

        :return: Dict, return the dictionary of twamp metrics result
        """
        self.click_enabled_element(self.locator.TWAMP_SENDER_DROP_DOWN, timeout)
        self.click_enabled_element(self.locator.CHOOSE_SELECT_PLAN_XPATH.format(session), timeout)
        self.wait_for_visibility(self.locator.TWAMP_SENDER_PROPERTY.format(session), timeout)
        return self._get_all_the_twamp_info(session)

    def _get_all_the_twamp_info(self, session):
        twamp_info = self._get_twamp_sender_session_info(session)
        twamp_info.update(self._get_one_way_and_two_way_packet_statistics())
        twamp_info.update(self._get_one_way_and_two_way_packet_delay_measurements())
        return twamp_info

    def _get_twamp_sender_session_info(self, session):
        twamp_sender_key = self.get_text_from_all_matching_elements(self.locator.TWAMP_SENDER_COLUMN.format(1))
        twamp_sender_value = self.get_text_from_all_matching_elements(self.locator.TWAMP_SENDER_COLUMN.format(2))
        return {"Twamp Sender {}".format(session): dict(zip(twamp_sender_key, twamp_sender_value))}

    def _get_one_way_and_two_way_packet_statistics(self):
        packet_statistic_key = self.get_text_from_all_matching_elements(self.locator.
                                                                        ONE_TWO_WAY_PACKET_STATISTIC_COLUMN.format(1))
        packet_statistic_value = self.get_text_from_all_matching_elements(self.locator.
                                                                          ONE_TWO_WAY_PACKET_STATISTIC_COLUMN.format(2))
        return {"One Way and Two Way Packet Statistics": dict(zip(packet_statistic_key, packet_statistic_value))}

    def _get_one_way_and_two_way_packet_delay_measurements(self):
        packet_delay_measurements_header = self.get_text_from_all_matching_elements(
            self.locator.ONE_WAY_TWO_WAY_PACKET_DELAY_MEASUREMENT_HEADER)
        packet_delay_measurements = {}
        packet_delay_measurements_key = self.get_text_from_all_matching_elements(
            self.locator.ONE_WAY_TWO_WAY_PACKET_DELAY_MEASUREMENT_COLUMN.format(1))
        for header in packet_delay_measurements_header:
            if header == "":
                continue
            index = packet_delay_measurements_header.index(header)
            packet_delay_measurements_value = self.get_text_from_all_matching_elements(
                self.locator.ONE_WAY_TWO_WAY_PACKET_DELAY_MEASUREMENT_COLUMN.format(index + 1))
            packet_delay_measurements[header] = dict(
                zip(packet_delay_measurements_key, packet_delay_measurements_value))
        return {"One Way and Two Way Packet Delay Measurements": packet_delay_measurements}
